   Column(Modifier.fillMaxWidth().background(Color.White,RoundedCornerShape(22.dp)).padding(16.dp)){Text("${catalog.size} illustrated exercises",color=ExerciseInk,fontSize=18.sp,fontWeight=FontWeight.Black);Text("Search by exercise, muscle or equipment",color=ExerciseMuted,fontSize=9.sp);Spacer(Modifier.height(9.dp));OutlinedTextField(query,{query=it;showCount=12},Modifier.fillMaxWidth(),singleLine=true,label={Text("Search exercises")});Spacer(Modifier.height(8.dp));filtered.take(showCount).forEach{e->Row(Modifier.fillMaxWidth().clickable{selected=e;mode="detail"}.padding(vertical=6.dp),verticalAlignment=Alignment.CenterVertically){RepDbImage(e.imageMain?:e.imageStart,Modifier.size(60.dp));Spacer(Modifier.width(10.dp));Column{Text(e.name,color=ExerciseInk,fontSize=12.sp,fontWeight=FontWeight.ExtraBold);Text("${e.group} · ${e.equipment}",color=ExerciseMuted,fontSize=8.sp);if(e.primaryMuscles.isNotEmpty())Text(e.primaryMuscles.take(2).joinToString(" · "){pretty(it)},color=ExerciseBlue,fontSize=8.sp)}}};if(filtered.size>showCount)Text("LOAD 12 MORE",color=ExerciseBlue,fontSize=10.sp,fontWeight=FontWeight.Black,textAlign=TextAlign.Center,modifier=Modifier.fillMaxWidth().clickable{showCount+=12}.padding(12.dp))}
