.sp)}};Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){OutlinedTextField(loadText,{loadText=it.filter{c->c.isDigit()||c=='.'}.take(6)},Modifier.weight(1f),singleLine=true,label={Text("kg")});OutlinedTextField(repsText,{repsText=it.filter(Char::isDigit).take(3)},Modifier.weight(1f),singleLine=true,label={Text("reps")})};Spacer(Modifier.height(8.dp));Box(Modifier.fillMaxWidth().background(ExerciseGreen,RoundedCornerShape(14.dp)).clickable{val r=repsText.toIntOrNull()?:0;val l=loadText.toDoubleOrNull()?:0.0;if(r>0){val set=NativeWorkoutSet(e,r,l,System.currentTimeMillis());session.add(set);scope.launch{NativeDataHub.saveValues(listOf(HealthValue(HealthDomain.EXERCISE,"exercise_set",set.volume,"kg-reps",set.timestamp,"repdb-exercise",mapOf("exerciseId" to e.id,"exerciseName" to e.name,"group" to e.group,"equipment" to e.equipment,"reps" to r.toString(),"loadKg" to l.toString(),"met" to e.met.toString()))));refresh()}}}.padding(13.dp),contentAlignment=Alignment.Center){Text("✓ COMPLETE SET",color=Color.White,fontSize=10.sp,fontWeight=FontWeight.Black)}};Spacer(Modifier.height(10.dp));Box(Modifier.fillMaxWidth().background(Color(0xFFEAF4FF),RoundedCornerShape(14.dp)).clickable{mode="library"}.padding(13.dp),contentAlignment=Alignment.Center){Text("+ CHOOSE / CHANGE EXERCISE",color=ExerciseBlue,fontSize=10.sp,fontWeight=FontWeight.Black)};if(status.isNotBlank())Text(status,color=ExerciseMuted,fontSize=8.sp,modifier=Modifier.padding(top=6.dp))}
